     5	import java.util.Collections;
     6	import java.util.List;
     7	
     8	public class EmailValidationRule implements MessageRule {
     9	    @Override
    10	    public List<ProcessedMessage> apply(OutgoingMessage message, boolean isTestMode) {
    11	        if (!isValidEmail(message.getTo())) {
    12	            return List.of(new ProcessedMessage(
    13	                message.getChannel(),
    14	                message.getTo(),
    15	                message.getSubject(),
    16	                message.getBody(),
    17	                MessageStatus.BLOCKED
    18	            ));
    19	        }
    20	        return Collections.emptyList();
    21	    }
    22	
    23	    private boolean isValidEmail(String email) {
    24	        if (email == null || email.isEmpty()) {
    25	            return false;
    26	        }
    27	
    28	        long atCount = email.chars().filter(ch -> ch == '@').count();
    29	        if (atCount != 1) {
    30	            return false;
    31	        }
    32	
    33	        int atIndex = email.indexOf('@');
    34	        if (atIndex == 0 || atIndex == email.length() - 1) {
    35	            return false;
    36	        }
    37	
    38	        String domain = email.substring(atIndex + 1);
    39	        return domain.contains(".");
    40	    }
    41	}
