     8	public class MessageProcessor {
     9	    private final boolean testMode;
    10	
    11	    public MessageProcessor(boolean testMode) {
    12	        this.testMode = testMode;
    13	    }
    14	
    15	    public List<ProcessedMessage> process(OutgoingMessage message) {
    16	        if (!isValidEmail(message.getTo())) {
    17	            return List.of(new ProcessedMessage(
    18	                message.getChannel(),
    19	                message.getTo(),
    20	                message.getSubject(),
    21	                message.getBody(),
    22	                MessageStatus.BLOCKED
    23	            ));
    24	        }
    25	
    26	        ProcessedMessage primaryMessage;
    27	        List<ProcessedMessage> additionalMessages = new ArrayList<>();
    28	
    29	        if (testMode) {
    30	            String newSubject = "[TESTE] " + message.getSubject();
    31	            String newBody = "Destinatário original: " + message.getTo() + "\n" + message.getBody();
    32	            primaryMessage = new ProcessedMessage(
    33	                message.getChannel(),
    34	                "testes@pousadamarealta.com.br",
    35	                newSubject,
    36	                newBody,
    37	                MessageStatus.SENT
    38	            );
    39	        } else {
    40	            primaryMessage = new ProcessedMessage(
    41	                message.getChannel(),
    42	                message.getTo(),
    43	                message.getSubject(),
    44	                message.getBody(),
    45	                MessageStatus.SENT
    46	            );
    47	
    48	            String archiveSubject = "[Cópia] " + message.getSubject();
    49	            ProcessedMessage archiveCopy = new ProcessedMessage(
    50	                message.getChannel(),
    51	                "arquivo@pousadamarealta.com.br",
    52	                archiveSubject,
    53	                message.getBody(),
    54	                MessageStatus.SENT
    55	            );
    56	            additionalMessages.add(archiveCopy);
    57	        }
    58	
    59	        List<ProcessedMessage> finalResults = new ArrayList<>();
    60	        finalResults.add(primaryMessage);
    61	        finalResults.addAll(additionalMessages);
    62	
    63	        return finalResults;
    64	    }
    65	
    66	    private boolean isValidEmail(String email) {
    67	        if (email == null || email.isEmpty()) {
    68	            return false;
    69	        }
    70	
    71	        long atCount = email.chars().filter(ch -> ch == '@').count();
    72	        if (atCount != 1) {
    73	            return false;
    74	        }
    75	
    76	        int atIndex = email.indexOf('@');
    77	        if (atIndex == 0 || atIndex == email.length() - 1) {
    78	            return false;
    79	        }
    80	
    81	        String domain = email.substring(atIndex + 1);
    82	        return domain.contains(".");
    83	    }
    84	}
