     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.Message;
     4	import com.pousadamarealta.messaging.MessageProcessor;
     5	import com.pousadamarealta.messaging.OutgoingMessage;
     6	import com.pousadamarealta.messaging.ProcessedMessage;
     7	
     8	import java.util.ArrayList;
     9	import java.util.List;
    10	import java.util.concurrent.atomic.AtomicLong;
    11	
    12	public class MessageService {
    13	    private final List<Message> messages = new ArrayList<>();
    14	    private final AtomicLong nextId = new AtomicLong(1);
    15	    private final MessageProcessor processor;
    16	
    17	    public MessageService(boolean testMode) {
    18	        this.processor = new MessageProcessor(testMode);
    19	    }
    20	
    21	    public void send(OutgoingMessage outgoing) {
    22	        List<ProcessedMessage> processed = processor.process(outgoing);
    23	
    24	        for (ProcessedMessage pm : processed) {
    25	            Message message = new Message(
    26	                nextId.getAndIncrement(),
    27	                pm.getChannel(),
    28	                pm.getTo(),
    29	                pm.getSubject(),
    30	                pm.getBody(),
    31	                pm.getStatus()
    32	            );
    33	            messages.add(message);
    34	        }
    35	    }
    36	
    37	    public List<Message> getAllMessages() {
    38	        return List.copyOf(messages);
    39	    }
    40	}
