     1	package com.pousadamarealta;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     6	import com.pousadamarealta.controller.MessageController;
     7	import com.pousadamarealta.controller.ReportController;
     8	import com.pousadamarealta.controller.ReservationController;
     9	import com.pousadamarealta.controller.RoomController;
    10	import com.pousadamarealta.service.MessageService;
    11	import com.pousadamarealta.service.ReportService;
    12	import com.pousadamarealta.service.ReservationService;
    13	import com.pousadamarealta.service.RoomService;
    14	import io.javalin.Javalin;
    15	import io.javalin.json.JavalinJackson;
    16	
    17	public class App {
    18	    public static void main(String[] args) {
    19	        int port = getPort();
    20	        boolean testMode = isTestMode();
    21	
    22	        RoomService roomService = new RoomService();
    23	        MessageService messageService = new MessageService(testMode);
    24	        ReservationService reservationService = new ReservationService(roomService, messageService);
    25	        ReportService reportService = new ReportService(reservationService, roomService);
    26	
    27	        RoomController roomController = new RoomController(roomService);
    28	        ReservationController reservationController = new ReservationController(reservationService, roomService);
    29	        MessageController messageController = new MessageController(messageService);
    30	        ReportController reportController = new ReportController(reportService);
    31	
    32	        ObjectMapper objectMapper = new ObjectMapper();
    33	        objectMapper.registerModule(new JavaTimeModule());
    34	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    35	
    36	        Javalin app = Javalin.create(config -> {
    37	            config.jsonMapper(new JavalinJackson(objectMapper, true));
    38	        });
    39	
    40	        app.get("/rooms", roomController::getRooms);
    41	        app.post("/reservations", reservationController::createReservation);
    42	        app.get("/reservations/{id}", reservationController::getReservation);
    43	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
    44	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
    45	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
    46	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
    47	        app.get("/reservations/{id}/document", reservationController::getDocument);
    48	        app.get("/messages", messageController::getMessages);
    49	        app.get("/reports/occupancy", reportController::getOccupancyReport);
    50	        app.get("/reports/revenue", reportController::getRevenueReport);
    51	
    52	        app.start(port);
    53	
    54	        System.out.println("Pousada Maré Alta - Reservation System");
    55	        System.out.println("Server started on port " + port);
    56	        System.out.println("Test mode: " + (testMode ? "ENABLED" : "DISABLED"));
    57	    }
    58	
    59	    private static int getPort() {
    60	        String portEnv = System.getenv("PORT");
    61	        if (portEnv != null && !portEnv.isEmpty()) {
    62	            try {
    63	                return Integer.parseInt(portEnv);
    64	            } catch (NumberFormatException e) {
    65	                System.err.println("Invalid PORT environment variable, using default 7070");
    66	            }
    67	        }
    68	        return 7070;
    69	    }
    70	
    71	    private static boolean isTestMode() {
    72	        String testModeEnv = System.getenv("HOTEL_TEST_MODE");
    73	        return "true".equalsIgnoreCase(testModeEnv);
    74	    }
    75	}
