     8	import java.time.LocalDate;
     9	
    10	public class PriceCalculator {
    11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    13	
    14	    public static BigDecimal calculateNightPrice(Room room, LocalDate night) {
    15	        BigDecimal basePrice = room.getNightlyRate();
    16	        if (isHighSeason(night)) {
    17	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
    18	        }
    19	        return round(basePrice);
    20	    }
    21	
    22	    public static BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    23	        BigDecimal subtotal = BigDecimal.ZERO;
    24	        LocalDate current = checkIn;
    25	        while (current.isBefore(checkOut)) {
    26	            subtotal = subtotal.add(calculateNightPrice(room, current));
    27	            current = current.plusDays(1);
    28	        }
    29	        return round(subtotal);
    30	    }
    31	
    32	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    33	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    34	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    35	        }
    36	        return BigDecimal.ZERO;
    37	    }
    38	
    39	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    40	        return round(subtotal.subtract(discount));
    41	    }
    42	
    43	    private static boolean isHighSeason(LocalDate date) {
    44	        int month = date.getMonthValue();
    45	        int day = date.getDayOfMonth();
    46	
    47	        if (month == 7) {
    48	            return true;
    49	        }
    50	
    51	        if (month == 12 && day >= 15) {
    52	            return true;
    53	        }
    54	
    55	        if (month == 1 || month == 2) {
    56	            return true;
    57	        }
    58	
    59	        return false;
    60	    }
    61	
    62	    private static BigDecimal round(BigDecimal value) {
    63	        return value.setScale(2, RoundingMode.HALF_EVEN);
    64	    }
    65	}

